def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # Interior singleton color supplies the ray color; edge runs encode two
    # parallel projections, at the run start and three cells inward.
    from collections import Counter
    counts=Counter(v for row in grid for v in row)
    bg=counts.most_common(1)[0][0]
    marks=[v for v,n in counts.items() if n==1 and v!=bg]
    ray=marks[0] if marks else None
    def runs(vals,color):
        res=[]; i=0
        while i<len(vals):
            if vals[i]==color:
                j=i
                while j+1<len(vals) and vals[j+1]==color:j+=1
                res.append((i,j));i=j+1
            else:i+=1
        return res
    if ray is not None:
        for edge in (0,w-1):
            vals=[grid[r][edge] for r in range(h)]
            for color in set(vals):
                if color==bg:continue
                for a,b in runs(vals,color):
                    for rr in (a,a+3):
                        if rr<=b:
                            for c in range(w):
                                if grid[rr][c]==bg:out[rr][c]=ray
        # Singletons emit toward the closest boundary along a straight ray.
        for r in range(h):
            for c in range(w):
                if grid[r][c]!=ray:continue
                hits=[]
                for dr,dc in ((0,-1),(0,1),(-1,0),(1,0)):
                    y,x=r+dr,c+dc
                    while 0<=y<h and 0<=x<w and grid[y][x]==bg:y+=dr;x+=dc
                    if 0<=y<h and 0<=x<w and grid[y][x]!=bg:hits.append((abs(y-r)+abs(x-c),dr,dc))
                if hits:
                    _,dr,dc=min(hits);out[r][c]=4
                    y,x=r+dr,c+dc
                    while 0<=y<h and 0<=x<w and grid[y][x]==bg:out[y][x]=ray;y+=dr;x+=dc
    return out
